import*as THREE from'three';
import{Component,Port,materials}from'../../core/index.js';
import{VisualJoint}from'../../core/components/VisualJoint.js';
import{addCadParts}from'../../modeling/cad.js';
import{mesh,slab,screw,FACE,portQuaternion}from'../../modeling/parts.js';
import{spec}from'./dimensions.js';import data from'./geometry-data.js';import{addStickers}from'./stickers.js';
const tau=Math.PI*2;
function bore(shape,x,y,r){const p=new THREE.Path();p.absarc(x,y,r,0,tau,false);shape.holes.push(p);}
function solid(parent,shape,depth,position,material,name){return mesh(parent,new THREE.ExtrudeGeometry(shape,{depth,bevelEnabled:false,curveSegments:48}),material,position,name);}
function discShape(r){const s=new THREE.Shape();s.absarc(0,0,r,0,tau,false);return s;}
function board(host){
 const s=new THREE.Shape(),x=10.4,y=-4,r=3.6,a=Math.acos((x-8)/r),dy=Math.sqrt(r*r-(x-8)**2);
 s.moveTo(-5.5,-14.5);s.lineTo(-7.7,-14.5);s.lineTo(-x,-12.5);s.lineTo(-x,y-dy);s.absarc(-8,y,r,Math.PI+a,Math.PI-a,false);s.lineTo(-x,12.4);s.lineTo(-8.5,14.3);s.lineTo(8.5,14.3);s.lineTo(x,12.4);s.lineTo(x,y+dy);s.absarc(8,y,r,a,tau-a,false);s.lineTo(x,-12.5);s.lineTo(7.7,-14.5);s.lineTo(5.5,-14.5);s.lineTo(5.5,-8.1);s.lineTo(-5.5,-8.1);s.closePath();bore(s,0,-4,2.65);
 const pcb=solid(host.body,s,.8,[0,0,-1.7],materials.plastic(0x17734f,{roughness:.87}),'MIC fixed green PCB with mounting edge reliefs and real retaining bore');pcb.userData={role:'physical-pcb',inferred:true,scope:'Appearance-only reconstruction from own PCB photograph;no traces,voltage or signal behavior'};
 const dark=materials.plastic(0x212820,{roughness:.82}),metal=materials.metal(0xb8bbaa,{roughness:.46}),ceramic=materials.plastic(0xb3a17e,{roughness:.86});
 const comparator=slab(host.body,3.9,4.9,1.55,.14,[6,8.6,-.9],dark,[],.015);comparator.name='MIC U1 LM393DR2G fixed SO8 comparator package';const comparatorLeads=[];for(const sign of[-1,1])for(let i=0;i<4;i++)comparatorLeads.push(mesh(host.body,new THREE.BoxGeometry(.9,.42,.2),metal,[6+sign*2.25,8.6+(i-1.5)*1.27,-.65],'MIC U1 LM393 physical SO8 lead '+(comparatorLeads.length+1)));
 const amplifier=slab(host.body,1.6,2.9,1,.08,[-3.9,9.35,-.9],dark,[],.015);amplifier.name='MIC U2 MAX4466 fixed five-lead low-noise preamplifier package';const amplifierLeads=[];for(const[dx,dy]of[[-1,-.95],[-1,0],[-1,.95],[1,-.95],[1,.95]])amplifierLeads.push(mesh(host.body,new THREE.BoxGeometry(.6,.34,.16),metal,[-3.9+dx,9.35+dy,-.68],'MIC U2 MAX4466 physical lead'));
 const regulator=slab(host.body,1.5,2.9,.95,.08,[-8,6,-.9],dark,[],.015);regulator.name='MIC U3 HT7533 fixed three-pin regulator';const regulatorLeads=[];for(const[dx,dy]of[[-.95,-.95],[-.95,.95],[.95,0]])regulatorLeads.push(mesh(host.body,new THREE.BoxGeometry(.6,.35,.16),metal,[-8+dx,6+dy,-.68],'MIC U3 HT7533 physical solder terminal'));
 const passives=[];for(const[n,x,y,w,h]of[['C2 bias',-4.5,12.9,1.6,.85],['R3 bias',-1.9,12.9,1.6,.85],['R5 bias',1.7,12.9,1.6,.85],['C3 coupling',-8.1,10.8,1.6,.85],['R4 bias',-6.8,9.05,1.3,.8],['R6 bias',-6.8,7.3,1.3,.8],['R7 feedback',-4.4,6.5,1.3,.8],['C7 feedback',-1.8,6.5,1.3,.8],['C8 feedback',-8.3,2.75,1.6,.85],['R8 feedback',-5.9,3.15,1.3,.8],['C9 output',8.4,2.9,1.6,.85],['R1 pullup',4.8,2.9,1.3,.8],['C1 supply',6.5,2.9,1.3,.8],['C4 supply',-8.3,.6,1.6,.85],['C5 supply',-6.1,.6,1.6,.85],['C6 input',-8.3,4.7,1.6,.85]]){const q=slab(host.body,w,h,.62,.055,[x,y,-.9],n[0]==='C'?ceramic:dark,[],.01);q.name='MIC fixed '+n;passives.push(q);for(const sign of[-1,1])mesh(host.body,new THREE.BoxGeometry(.23,h,.18),metal,[x+sign*(w/2-.08),y,-.72],'MIC passive solder end');}
 return{pcb,comparator,comparatorLeads,amplifier,amplifierLeads,regulator,regulatorLeads,passives};
}
function microphone(host){
 const g=new THREE.Group();g.name='MIC physical stationary electret microphone can and acoustic chamber';g.position.set(0,10,0);host.body.add(g);const metal=materials.metal(0xaeb3ad,{roughness:.42});
 const ring=discShape(2.55);bore(ring,0,0,2.3);const can=solid(g,ring,4.2,[0,0,-.65],metal,'MIC real hollow metallic microphone can with inward-facing chamber walls');
 const base=mesh(g,new THREE.CylinderGeometry(2.55,2.55,.25,72).rotateX(Math.PI/2),materials.plastic(0x303a30,{roughness:.88}),[0,0,-.7],'MIC fixed microphone rear insulating base');
 const diaphragm=mesh(g,new THREE.CylinderGeometry(2.29,2.29,.08,72).rotateX(Math.PI/2),materials.plastic(0x1d251f,{roughness:.94}),[0,0,3.14],'MIC physical recessed acoustic diaphragm behind air space');
 const screenShape=discShape(spec.microphone.screenRadiusMm),holes=[],pitch=spec.microphone.screenPitchMm,rad=spec.microphone.screenBoreRadiusMm;
 for(let row=-5;row<=5;row++)for(let col=-5;col<=5;col++){const x=(col+(Math.abs(row)%2)*.5)*pitch,y=row*pitch*Math.sqrt(3)/2;if(Math.hypot(x,y)+rad>2.17)continue;bore(screenShape,x,y,rad);holes.push([x,y]);}
 const screen=solid(g,screenShape,.08,[0,0,3.4],materials.metal(0x566158,{roughness:.9}),'MIC physical perforated dark metal acoustic screen with positive bore clearance');screen.userData={role:'physical-acoustic-screen',boreRadiusMm:rad,boreCentersMm:holes,minimumOuterMaterialMm:Math.min(...holes.map(([x,y])=>spec.microphone.screenRadiusMm-Math.hypot(x,y)-rad)),inferred:true};
 const rim=discShape(2.55);bore(rim,0,0,2.3);const lip=solid(g,rim,.08,[0,0,3.55],metal,'MIC rolled silver lip around real recessed acoustic screen');const leads=[];for(const x of[-1.2,1.2]){leads.push(mesh(g,new THREE.CylinderGeometry(.25,.25,.8,16).rotateX(Math.PI/2),metal,[x,0,-.9],'MIC physical soldered electret terminal'));mesh(g,new THREE.CylinderGeometry(.43,.43,.12,24).rotateX(Math.PI/2),metal,[x,0,-1.72],'MIC rear solder joint');}
 const anchor=host.add(new Component({id:'sensor',label:'MIC passive acoustic package anchor',position:spec.microphone.position,meta:{role:'visual-anchor',scope:'Package appearance/position only;no sound,waveform,ADC,recording,threshold,GPIO,sampling or microphone signal commands'}}));return{group:g,can,base,diaphragm,screen,lip,leads,anchor};
}
function trimmer(host){
 const position=spec.trimmer.position,metal=materials.metal(0xa8ada5,{roughness:.42}),blue=materials.plastic(0x086ec4,{roughness:.64}),dark=materials.plastic(0x194e7c,{roughness:.9});
 const s=new THREE.Shape();s.moveTo(-3.35,-3.45);s.lineTo(3.35,-3.45);s.lineTo(3.35,3.45);s.lineTo(-3.35,3.45);s.closePath();bore(s,0,0,1.4);const body=solid(host.body,s,4.2,[0,position[1],-.45],blue,'MIC R2 fixed blue 10K threshold trimmer body with real spindle recess');
 const base=slab(host.body,6.9,7.1,.3,.06,[0,position[1],-.75],materials.plastic(0x174b72,{roughness:.81}),[],.01);base.name='MIC R2 fixed physical trimmer base behind square opening';for(const[x,y]of[[-2.54,-2.54],[2.54,-2.54],[2.54,2.54]])mesh(host.body,new THREE.BoxGeometry(.55,.55,.65),metal,[x,position[1]+y,-.8],'MIC R2 fixed solder terminal into PCB');
 const ticks=[];for(let i=0;i<13;i++){const angle=(-135+i*22.5)*Math.PI/180,t=mesh(host.body,new THREE.BoxGeometry(.11,i%3===0?.5:.3,.012),dark,[Math.sin(angle)*1.95,position[1]+Math.cos(angle)*1.95,3.756],'MIC fixed threshold scale tick');t.rotation.z=-angle;ticks.push(t);}
 const cap=new THREE.Group();cap.name='MIC R2 moving physical recessed cross-slotted adjustment head';cap.position.fromArray(position);host.body.add(cap);const r=1.3,w=.2,a=Math.asin(w/r),headParts=[];for(let i=0;i<4;i++){const q=new THREE.Shape();q.moveTo(w,w);q.lineTo(Math.sqrt(r*r-w*w),w);q.absarc(0,0,r,a,Math.PI/2-a,false);q.closePath();const lobe=solid(cap,q,.22,[0,0,-.1],metal,'MIC actual cross-head lobe '+(i+1));lobe.rotation.z=i*Math.PI/2;headParts.push(lobe);}
 const floor=mesh(cap,new THREE.CylinderGeometry(1.3,1.3,.15,64).rotateX(Math.PI/2),materials.plastic(0x343c35,{roughness:.84}),[0,0,-.18],'MIC physical recessed screwdriver cross-slot floor');const shaft=mesh(cap,new THREE.CylinderGeometry(.8,.8,3.8,48).rotateX(Math.PI/2),metal,[0,0,-2.05],'MIC actual moving adjustment spindle into fixed body');
 const joint=host.add(new VisualJoint({id:'threshold',label:'R2 threshold screwdriver-head angle',position,axis:spec.trimmer.axis,limitsDeg:spec.trimmer.limitsDeg,meta:{role:'externally-driven-visual-joint',rangeEvidence:spec.trimmer.rangeEvidence,scope:'External finite angle/duration only;no resistance,voltage,digital threshold,ADC,recording,sampling,electrical or firmware behavior'}}));joint.adopt(cap);return{body,base,ticks,cap,headParts,floor,shaft,joint};
}
function grove(host){
 const g=new THREE.Group();g.name='MIC physical open black HY2.0-4P socket';g.position.fromArray(spec.grove.position);g.quaternion.copy(FACE.bottom);host.body.add(g);const plastic=materials.plastic(spec.grove.color,{roughness:.75}),metal=materials.metal(0xb8b9a7,{roughness:.44}),box=(s,p,n,m=plastic)=>mesh(g,new THREE.BoxGeometry(...s),m,p,'MIC Grove '+n),depth=6.3;
 for(const sign of[-1,1]){box([.65,5.2,depth],[sign*4.675,0,-depth/2],'side wall');box([.7,.6,3.2],[sign*3.85,2.3,-4.7],'guide rail');box([.6,.45,1.2],[sign*3.65,2.375,-1.8],'latch shoulder');}box([8.7,.65,depth],[0,-2.275,-depth/2],'floor');box([8.7,4.55,.65],[0,.325,-depth+.325],'rear wall');box([4.8,.45,2.3],[0,2.375,-4.5],'locking bridge');const contacts=[];for(let i=0;i<4;i++){contacts.push(box([.42,.42,4.5],[(i-1.5)*2,.2,-3.6],`contact ${i+1}`,metal));box([.42,1.4,.42],[(i-1.5)*2,-2.7,-5.8],`tail ${i+1}`,metal);}
 const port=host.add(new Port({id:'grove',label:'PORT.B · I/O',connector:'grove',position:spec.grove.position,quaternion:portQuaternion('bottom'),hitSize:[10,1,5.2],pins:[{n:1,name:'GND',color:'black'},{n:2,name:'5V',color:'red'},{n:3,name:'D.OUT',color:'yellow'},{n:4,name:'A.OUT',color:'white'}],meta:{role:'visual-connector',face:'bottom',scope:'Physical attachment,four contacts and documented labels only;no voltage,ADC,GPIO,electrical or firmware model'}}));return{group:g,contacts,port};
}
export function buildMIC(host){
 const parts=addCadParts(host,data,{shell:materials.plastic(0xe8e9e3,{roughness:.79})}),pcb=board(host),acoustic=microphone(host),threshold=trimmer(host),input=grove(host),fixing=screw(host.body,[0,-4,-3.88],'back',1.28);fixing.name='MIC fixed recessed rear retaining hex screw';mesh(host.body,new THREE.CylinderGeometry(.62,.62,3.7,32).rotateX(Math.PI/2),materials.metal(0x999f91),[0,-4,-1.9],'MIC concealed fixed retaining screw shank');
 const backCarrier=slab(host.body,16,12.2,.05,.05,[0,7.35,-3.845],materials.plastic(0xdfe1dc,{roughness:.88}),[],.005);backCarrier.name='MIC physical rear adhesive substrate independent of printing';host.micAssembly={parts,pcb,microphone:acoustic,trimmer:threshold,input,fixing,backCarrier};host.unitStickers=addStickers(host);
}
